template <int Base, int Exp>
struct CompileTimePower {
    static constexpr long value =
        Base * CompileTimePower<Base, Exp - 1>::value;
};

// Base case specialization
template <int Base>
struct CompileTimePower<Base, 0> {
    static constexpr long value = 1;
};

// Usage: Zero runtime overhead (no loops or function calls)
// All computation done during template instantiation phase.
static constexpr long RESULT_A = CompileTimePower<3, 4>::value;

// Equivalent modern zero-overhead abstraction (C++14/17)
template <int N>
constexpr int factorial() {
    if constexpr (N <= 1) return 1;
    return N * factorial<N - 1>();
}

static constexpr int RESULT_B = factorial<5>();
